"""Commands generated by the policy run only in disposable Docker containers."""
from __future__ import annotations
import re
import shlex
import subprocess
import uuid
from .core import StudyError


def docker(executable, args, timeout=120):
    try:
        p = subprocess.run([executable, *args], capture_output=True, timeout=timeout)
    except (OSError, subprocess.TimeoutExpired):
        raise StudyError("Docker command failed or timed out") from None
    if p.returncode:
        raise StudyError("Docker operation failed: " + p.stderr.decode("utf-8", "replace")[-1500:])
    return p.stdout.decode("utf-8", "replace")


def inspect_image(executable, image):
    import json
    return json.loads(docker(executable, ["image", "inspect", image]))[0]


class DockerSession:
    def __init__(self, image_id, base_commit, settings, ttl=3800):
        if not re.fullmatch(r"[0-9a-f]{40}", base_commit):
            raise StudyError("Invalid task base commit")
        self.exe = settings.get("executable", "docker")
        self.base = base_commit
        self.container = None
        self.settings = settings
        self.container = docker(self.exe, ["run", "-d", "--rm", "--network", "none", "--memory", settings.get("memory", "8g"), "--cpus", str(settings.get("cpus", 4)), "--pids-limit", str(settings.get("pids_limit", 1024)), "--label", "experiment=d3-bon-study", "--name", "d3study-" + uuid.uuid4().hex[:12], "--workdir", "/testbed", image_id, "sleep", str(ttl)], timeout=120).strip()
        try:
            r = self.execute("git reset --hard " + shlex.quote(base_commit), 60, trusted=True)
            s = self.execute("git rev-parse HEAD", 30, trusted=True)
            if r["returncode"] or s["output"].strip() != base_commit:
                raise StudyError("Fresh container could not checkout the pinned task base")
        except BaseException:
            self.close()
            raise

    def execute(self, command, timeout, *, trusted=False):
        if not self.container:
            raise StudyError("Container is not running")
        limit = max(1, int(timeout))
        shell = "/bin/bash --noprofile --norc" if trusted else "bash"
        wrapped = "/usr/bin/timeout --signal=TERM --kill-after=5s " + str(limit) + "s " + shell + " -c " + shlex.quote(command)
        environment = ["-e", "BASH_ENV=", "-e", "PATH=/usr/bin:/bin"] if trusted else ["-e", "BASH_ENV=/root/.bashrc"]
        try:
            p = subprocess.run([self.exe, "exec", "--workdir", "/testbed", *environment, "-e", "PAGER=cat", self.container, "/bin/bash", "--noprofile", "--norc", "-c", wrapped], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=limit + 10)
            return {"returncode": p.returncode, "output": p.stdout.decode("utf-8", "replace")}
        except subprocess.TimeoutExpired as error:
            return {"returncode": 124, "output": (error.stdout or b"").decode("utf-8", "replace"), "controller_timeout": True}
        except OSError:
            raise StudyError("Docker execution unavailable") from None

    def extract(self):
        # These operations affect only our disposable container, never the host.
        add = self.execute("git ls-files --others --exclude-standard -z | xargs -0 -r git add -N --", 30, trusted=True)
        diff = self.execute("git -c core.quotePath=false diff --no-ext-diff --binary " + self.base + " -- .", 30, trusted=True)
        names = self.execute("git diff --no-ext-diff --name-only -z " + self.base + " -- .", 30, trusted=True)
        if add["returncode"] or diff["returncode"] or names["returncode"]:
            raise StudyError("Final patch extraction failed")
        return diff["output"], [s for s in names["output"].split("\0") if s]

    def close(self):
        if self.container:
            subprocess.run([self.exe, "rm", "-f", self.container], capture_output=True, timeout=60)
            self.container = None
